module ietf-system {
  namespace "urn:ietf:params:xml:ns:yang:ietf-system";
  prefix sys;

  organization
    "IETF NETMOD (NETCONF Data Modeling Language) Working Group";
  contact
    "WG Web:   <http://tools.ietf.org/wg/netmod/>
     WG List:  <mailto:netmod@ietf.org>

     WG Chair: Thomas Nadeau
               <mailto:tnadeau@lucidvision.com>

     WG Chair: Juergen Schoenwaelder
               <mailto:j.schoenwaelder@jacobs-university.de>

     Editor:   Andy Bierman
               <mailto:andy@yumaworks.com>

     Editor:   Martin Bjorklund
               <mailto:mbj@tail-f.com>";
  description
    "This module contains a collection of YANG definitions for the
     configuration and identification of some common system
     properties within a device containing a NETCONF server.  This
     includes data node definitions for system identification,
     time-of-day management, user management, DNS resolver
     configuration, and some protocol operations for system
     management.

     Copyright (c) 2014 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (http://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC 7317; see
     the RFC itself for full legal notices.";

  revision 2014-08-06;

  identity authentication-method {
    derived radius;
    derived local-users;
    description
      "Base identity for user authentication methods.";
  }

  identity radius {
    description
      "Indicates user authentication using RADIUS.";
    reference
      "RFC 2865: Remote Authentication Dial In User Service (RADIUS)
       RFC 5607: Remote Authentication Dial-In User Service (RADIUS)
                 Authorization for Network Access Server (NAS)
                 Management";
  }

  identity local-users {
    description
      "Indicates password-based authentication of locally
       configured users.";
  }

  identity radius-authentication-type {
    derived radius-pap;
    derived radius-chap;
    description
      "Base identity for RADIUS authentication types.";
  }

  identity radius-pap {
    description
      "The device requests Password Authentication Protocol (PAP)
       authentication from the RADIUS server.";
    reference
      "RFC 2865: Remote Authentication Dial In User Service (RADIUS)";
  }

  identity radius-chap {
    description
      "The device requests Challenge Handshake Authentication
       Protocol (CHAP) authentication from the RADIUS server.";
    reference
      "RFC 2865: Remote Authentication Dial In User Service (RADIUS)";
  }

  container system {
    config true;
    status current;
    description
      "System group configuration.";
    leaf contact {
      type string;
      config true;
      status current;
      description
        "The administrator contact information for the system.

         A server implementation MAY map this leaf to the sysContact
         MIB object.  Such an implementation needs to use some
         mechanism to handle the differences in size and characters
         allowed between this leaf and sysContact.  The definition of
         such a mechanism is outside the scope of this document.";
      reference
        "RFC 3418: Management Information Base (MIB) for the
                   Simple Network Management Protocol (SNMP)
                   SNMPv2-MIB.sysContact";
    }
    leaf hostname {
      type string {
        length "1..253";
        pattern "((([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.)*([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.?)|\\.";
      }
      config true;
      status current;
      description
        "The name of the host.  This name can be a single domain
         label or the fully qualified domain name of the host.";
    }
    leaf location {
      type string;
      config true;
      status current;
      description
        "The system location.

         A server implementation MAY map this leaf to the sysLocation
         MIB object.  Such an implementation needs to use some
         mechanism to handle the differences in size and characters
         allowed between this leaf and sysLocation.  The definition
         of such a mechanism is outside the scope of this document.";
      reference
        "RFC 3418: Management Information Base (MIB) for the
                   Simple Network Management Protocol (SNMP)
                   SNMPv2-MIB.sysLocation";
    }
    container clock {
      config true;
      status current;
      description
        "Configuration of the system date and time properties.";
      choice timezone {
        config true;
        status current;
        description
          "The system time zone information.";
        case timezone-name {
          config true;
          status current;
          leaf timezone-name {
            type string;
            config true;
            status current;
            description
              "The TZ database name to use for the system, such
               as 'Europe/Stockholm'.";
          }
        }
        case timezone-utc-offset {
          config true;
          status current;
          leaf timezone-utc-offset {
            type int16 {
              range "-1500..1500";
            }
            units "minutes";
            config true;
            status current;
            description
              "The number of minutes to add to UTC time to
               identify the time zone for this system.  For example,
               'UTC - 8:00 hours' would be represented as '-480'.
               Note that automatic daylight saving time adjustment
               is not provided if this object is used.";
          }
        }
      }
    }
    container ntp {
      presence "true";
      config true;
      status current;
      description
        "Configuration of the NTP client.";
      leaf enabled {
        type boolean;
        default "true";
        config true;
        status current;
        description
          "Indicates that the system should attempt to
           synchronize the system clock with an NTP server
           from the 'ntp/server' list.";
      }
      list server {
        key "name";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "List of NTP servers to use for system clock
           synchronization.  If '/system/ntp/enabled'
           is 'true', then the system will attempt to
           contact and utilize the specified NTP servers.";
        leaf name {
          type string;
          config true;
          status current;
          description
            "An arbitrary name for the NTP server.";
        }
        choice transport {
          config true;
          mandatory true;
          status current;
          description
            "The transport-protocol-specific parameters for this
             server.";
          case udp {
            config true;
            status current;
            container udp {
              config true;
              status current;
              description
                "Contains UDP-specific configuration parameters
                 for NTP.";
              leaf address {
                type union {
                  type string {
                    pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                  }
                  type string {
                    pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                    pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                  }
                  type string {
                    length "2..253";
                    pattern "((([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.)*([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.?)|\\.";
                    pattern "[a-zA-Z0-9\\-\\.]+";
                  }
                }
                config true;
                mandatory true;
                status current;
                description
                  "The address of the NTP server.";
              }
              leaf port {
                type uint16 {
                  range "0..65535";
                }
                default "123";
                config true;
                status current;
                description
                  "The port number of the NTP server.";
              }
            }
          }
        }
        leaf association-type {
          type enumeration {
            enum "server" {
              value 0;
              status current;
              description
                "Use client association mode.  This device
                 will not provide synchronization to the
                 configured NTP server.";
            }
            enum "peer" {
              value 1;
              status current;
              description
                "Use symmetric active association mode.
                 This device may provide synchronization
                 to the configured NTP server.";
            }
            enum "pool" {
              value 2;
              status current;
              description
                "Use client association mode with one or
                 more of the NTP servers found by DNS
                 resolution of the domain name given by
                 the 'address' leaf.  This device will not
                 provide synchronization to the servers.";
            }
          }
          default "server";
          config true;
          status current;
          description
            "The desired association type for this NTP server.";
        }
        leaf iburst {
          type boolean;
          default "false";
          config true;
          status current;
          description
            "Indicates whether this server should enable burst
             synchronization or not.";
        }
        leaf prefer {
          type boolean;
          default "false";
          config true;
          status current;
          description
            "Indicates whether this server should be preferred
             or not.";
        }
      }
    }
    container dns-resolver {
      config true;
      status current;
      description
        "Configuration of the DNS resolver.";
      leaf-list search {
        type string {
          length "1..253";
          pattern "((([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.)*([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.?)|\\.";
        }
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "An ordered list of domains to search when resolving
           a host name.";
      }
      list server {
        key "name";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "List of the DNS servers that the resolver should query.

           When the resolver is invoked by a calling application, it
           sends the query to the first name server in this list.  If
           no response has been received within 'timeout' seconds,
           the resolver continues with the next server in the list.
           If no response is received from any server, the resolver
           continues with the first server again.  When the resolver
           has traversed the list 'attempts' times without receiving
           any response, it gives up and returns an error to the
           calling application.

           Implementations MAY limit the number of entries in this
           list.";
        leaf name {
          type string;
          config true;
          status current;
          description
            "An arbitrary name for the DNS server.";
        }
        choice transport {
          config true;
          mandatory true;
          status current;
          description
            "The transport-protocol-specific parameters for this
             server.";
          case udp-and-tcp {
            config true;
            status current;
            container udp-and-tcp {
              config true;
              status current;
              description
                "Contains UDP- and TCP-specific configuration
                 parameters for DNS.";
              reference
                "RFC 1035: Domain Names - Implementation and
                           Specification
                 RFC 5966: DNS Transport over TCP - Implementation
                           Requirements";
              leaf address {
                type union {
                  type string {
                    pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                  }
                  type string {
                    pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                    pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                  }
                }
                config true;
                mandatory true;
                status current;
                description
                  "The address of the DNS server.";
              }
              leaf port {
                type uint16 {
                  range "0..65535";
                }
                default "53";
                config true;
                status current;
                description
                  "The UDP and TCP port number of the DNS server.";
              }
            }
          }
        }
      }
      container options {
        config true;
        status current;
        description
          "Resolver options.  The set of available options has been
           limited to those that are generally available across
           different resolver implementations and generally useful.";
        leaf timeout {
          type uint8 {
            range "1..255";
          }
          units "seconds";
          default "5";
          config true;
          status current;
          description
            "The amount of time the resolver will wait for a
             response from each remote name server before
             retrying the query via a different name server.";
        }
        leaf attempts {
          type uint8 {
            range "1..255";
          }
          default "2";
          config true;
          status current;
          description
            "The number of times the resolver will send a query to
             all of its name servers before giving up and returning
             an error to the calling application.";
        }
      }
    }
    container radius {
      config true;
      status current;
      description
        "Configuration of the RADIUS client.";
      list server {
        key "name";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "List of RADIUS servers used by the device.

           When the RADIUS client is invoked by a calling
           application, it sends the query to the first server in
           this list.  If no response has been received within
           'timeout' seconds, the client continues with the next
           server in the list.  If no response is received from any
           server, the client continues with the first server again.
           When the client has traversed the list 'attempts' times
           without receiving any response, it gives up and returns an
           error to the calling application.";
        leaf name {
          type string;
          config true;
          status current;
          description
            "An arbitrary name for the RADIUS server.";
        }
        choice transport {
          config true;
          mandatory true;
          status current;
          description
            "The transport-protocol-specific parameters for this
             server.";
          case udp {
            config true;
            status current;
            container udp {
              config true;
              status current;
              description
                "Contains UDP-specific configuration parameters
                 for RADIUS.";
              leaf address {
                type union {
                  type string {
                    pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                  }
                  type string {
                    pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                    pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                  }
                  type string {
                    length "2..253";
                    pattern "((([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.)*([a-zA-Z0-9_]([a-zA-Z0-9\\-_]){0,61})?[a-zA-Z0-9]\\.?)|\\.";
                    pattern "[a-zA-Z0-9\\-\\.]+";
                  }
                }
                config true;
                mandatory true;
                status current;
                description
                  "The address of the RADIUS server.";
              }
              leaf authentication-port {
                type uint16 {
                  range "0..65535";
                }
                default "1812";
                config true;
                status current;
                description
                  "The port number of the RADIUS server.";
              }
              leaf shared-secret {
                ietf-netconf-acm:default-deny-all;
                type string;
                config true;
                mandatory true;
                status current;
                description
                  "The shared secret, which is known to both the
                   RADIUS client and server.";
                reference
                  "RFC 2865: Remote Authentication Dial In User
                             Service (RADIUS)";
              }
            }
          }
        }
        leaf authentication-type {
          type identityref {
            base radius-authentication-type;
          }
          default "radius-pap";
          config true;
          status current;
          description
            "The authentication type requested from the RADIUS
             server.";
        }
      }
      container options {
        config true;
        status current;
        description
          "RADIUS client options.";
        leaf timeout {
          type uint8 {
            range "1..255";
          }
          units "seconds";
          default "5";
          config true;
          status current;
          description
            "The number of seconds the device will wait for a
             response from each RADIUS server before trying with a
             different server.";
        }
        leaf attempts {
          type uint8 {
            range "1..255";
          }
          default "2";
          config true;
          status current;
          description
            "The number of times the device will send a query to
             all of its RADIUS servers before giving up.";
        }
      }
    }
    container authentication {
      ietf-netconf-acm:default-deny-write;
      config true;
      status current;
      description
        "The authentication configuration subtree.";
      leaf-list user-authentication-order {
        ietf-netconf-acm:default-deny-write;
        type identityref {
          base authentication-method;
        }
        must "(. != \"sys:radius\" or ../../radius/server)" {
          error-message
            "When 'radius' is used, a RADIUS server must be configured.";
          description
            "When 'radius' is used as an authentication method,
             a RADIUS server must be configured.";
        }
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "When the device authenticates a user with a password,
           it tries the authentication methods in this leaf-list in
           order.  If authentication with one method fails, the next
           method is used.  If no method succeeds, the user is
           denied access.

           An empty user-authentication-order leaf-list still allows
           authentication of users using mechanisms that do not
           involve a password.

           If the 'radius-authentication' feature is advertised by
           the NETCONF server, the 'radius' identity can be added to
           this list.

           If the 'local-users' feature is advertised by the
           NETCONF server, the 'local-users' identity can be
           added to this list.";
      }
      list user {
        ietf-netconf-acm:default-deny-write;
        key "name";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "The list of local users configured on this device.";
        leaf name {
          ietf-netconf-acm:default-deny-write;
          type string;
          config true;
          status current;
          description
            "The user name string identifying this entry.";
        }
        leaf password {
          ietf-netconf-acm:default-deny-write;
          type string {
            pattern "$0$.*|$1$[a-zA-Z0-9./]{1,8}$[a-zA-Z0-9./]{22}|$5$(rounds=\\d+$)?[a-zA-Z0-9./]{1,16}$[a-zA-Z0-9./]{43}|$6$(rounds=\\d+$)?[a-zA-Z0-9./]{1,16}$[a-zA-Z0-9./]{86}";
          }
          config true;
          status current;
          description
            "The password for this entry.";
        }
        list authorized-key {
          ietf-netconf-acm:default-deny-write;
          key "name";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "A list of public SSH keys for this user.  These keys
             are allowed for SSH authentication, as described in
             RFC 4253.";
          reference
            "RFC 4253: The Secure Shell (SSH) Transport Layer
                       Protocol";
          leaf name {
            ietf-netconf-acm:default-deny-write;
            type string;
            config true;
            status current;
            description
              "An arbitrary name for the SSH key.";
          }
          leaf algorithm {
            ietf-netconf-acm:default-deny-write;
            type string;
            config true;
            mandatory true;
            status current;
            description
              "The public key algorithm name for this SSH key.

               Valid values are the values in the IANA 'Secure Shell
               (SSH) Protocol Parameters' registry, Public Key
               Algorithm Names.";
            reference
              "IANA 'Secure Shell (SSH) Protocol Parameters'
               registry, Public Key Algorithm Names";
          }
          leaf key-data {
            ietf-netconf-acm:default-deny-write;
            type binary;
            config true;
            mandatory true;
            status current;
            description
              "The binary public key data for this SSH key, as
               specified by RFC 4253, Section 6.6, i.e.:

                 string    certificate or public key format
                           identifier
                 byte[n]   key/certificate data.";
            reference
              "RFC 4253: The Secure Shell (SSH) Transport Layer
                         Protocol";
          }
        }
      }
    }
  }
  container system-state {
    config false;
    status current;
    description
      "System group operational state.";
    container platform {
      config false;
      status current;
      description
        "Contains vendor-specific information for
         identifying the system platform and operating system.";
      reference
        "IEEE Std 1003.1-2008 - sys/utsname.h";
      leaf os-name {
        type string;
        config false;
        status current;
        description
          "The name of the operating system in use -
           for example, 'Linux'.";
        reference
          "IEEE Std 1003.1-2008 - utsname.sysname";
      }
      leaf os-release {
        type string;
        config false;
        status current;
        description
          "The current release level of the operating
           system in use.  This string MAY indicate
           the OS source code revision.";
        reference
          "IEEE Std 1003.1-2008 - utsname.release";
      }
      leaf os-version {
        type string;
        config false;
        status current;
        description
          "The current version level of the operating
           system in use.  This string MAY indicate
           the specific OS build date and target variant
           information.";
        reference
          "IEEE Std 1003.1-2008 - utsname.version";
      }
      leaf machine {
        type string;
        config false;
        status current;
        description
          "A vendor-specific identifier string representing
           the hardware in use.";
        reference
          "IEEE Std 1003.1-2008 - utsname.machine";
      }
    }
    container clock {
      config false;
      status current;
      description
        "Monitoring of the system date and time properties.";
      leaf current-datetime {
        type string {
          pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
        }
        config false;
        status current;
        description
          "The current system date and time.";
      }
      leaf boot-datetime {
        type string {
          pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
        }
        config false;
        status current;
        description
          "The system date and time when the system last restarted.";
      }
    }
  }

  rpc set-current-datetime {
    ietf-netconf-acm:default-deny-all;
    status current;
    description
      "Set the /system-state/clock/current-datetime leaf
       to the specified value.

       If the system is using NTP (i.e., /system/ntp/enabled
       is set to 'true'), then this operation will fail with
       error-tag 'operation-failed' and error-app-tag value of
       'ntp-active'.";

    input {
      leaf current-datetime {
        ietf-netconf-acm:default-deny-all;
        type string {
          pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
        }
        mandatory true;
        status current;
        description
          "The current system date and time.";
      }
    }
  }
  rpc system-restart {
    ietf-netconf-acm:default-deny-all;
    status current;
    description
      "Request that the entire system be restarted immediately.
       A server SHOULD send an rpc reply to the client before
       restarting the system.";
  }
  rpc system-shutdown {
    ietf-netconf-acm:default-deny-all;
    status current;
    description
      "Request that the entire system be shut down immediately.
       A server SHOULD send an rpc reply to the client before
       shutting down the system.";
  }
}
